// =========================================================================
// Title: Nebula
// A procedural copy of a Hubble-style image of a star-forming region
// (Library > Textures > Images > 54782043516_0c1287aa5a_o.jpg): glowing
// blue-white gas in the upper part, brown dust lanes and dark pillars, an
// orange knot low in the middle, a dark lower-left corner, and stars, the
// brightest with four diffraction spikes.
//
// Sliders (the lower ones, so they never touch the surface's constants):
//   D  dust:  0 none, 1 as in the image, 2 twice as thick
//   E  stars: 0 none, 1 as in the image, 2 twice as bright
//   F  drift of the gas: 0 still, 1 slow
// =========================================================================

float nb_hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float nb_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = nb_hash(i);
    float b = nb_hash(i + vec2(1.0, 0.0));
    float c = nb_hash(i + vec2(0.0, 1.0));
    float d = nb_hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// Soft clouds: six octaves, each turned and shifted.
float nb_fbm(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int k = 0; k < 6; k++) {
        s += a * nb_noise(p);
        p = mat2(1.6, 1.2, -1.2, 1.6) * p + 7.3;
        a *= 0.5;
    }
    return s;
}

// Ridged clouds: thin crests, the shape of the dust filaments.
float nb_ridge(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int k = 0; k < 5; k++) {
        float n = 1.0 - abs(2.0 * nb_noise(p) - 1.0);
        s += a * n * n;
        p = mat2(1.7, 1.1, -1.1, 1.7) * p + 3.1;
        a *= 0.5;
    }
    return s;
}

// At most one star per cell of a grid, at a random place and brightness,
// blue-white or orange; with spikes > 0 also four diffraction spikes.
vec3 nb_stars(vec2 p, float cells, float rate, float coreK, float spikes) {
    vec2 g = p * cells;
    vec2 id = floor(g);
    if (nb_hash(id) > rate) return vec3(0.0);
    vec2 d = fract(g) - 0.5 - 0.6 * (vec2(nb_hash(id + 3.1), nb_hash(id + 7.7)) - 0.5);
    float b = 0.2 + 0.8 * pow(nb_hash(id + 1.9), 3.0);
    float r2 = dot(d, d);
    float light = exp(-r2 * coreK) + 0.2 * exp(-r2 * coreK * 0.06);
    if (spikes > 0.0) {
        float sx = exp(-abs(d.y) * 170.0) * exp(-abs(d.x) * 6.0);
        float sy = exp(-abs(d.x) * 170.0) * exp(-abs(d.y) * 6.0);
        light += spikes * (sx + sy) * b;
    }
    vec3 tint = nb_hash(id + 5.3) < 0.3 ? vec3(1.0, 0.62, 0.38) : vec3(0.78, 0.86, 1.0);
    return tint * light * b;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    float dust = ubuf.u_mathParams2.x;          // D
    float starsAmount = ubuf.u_mathParams2.y;   // E
    float drift = ubuf.u_mathParams2.z * iTime * 0.02;   // F
    vec2 p = uv * 3.0;

    // THE GAS: clouds warped by clouds, lit by two glows (upper middle and
    // right edge, where the image is bright).
    vec2 q = vec2(nb_fbm(p + vec2(0.0, drift)), nb_fbm(p + vec2(5.2, 1.3) - drift));
    float gas = nb_fbm(p + 3.0 * q);
    float glow = clamp(0.95 * exp(-2.2 * length((uv - vec2(0.55, 0.78)) * vec2(1.1, 1.5)))
                       + 0.75 * exp(-3.0 * length((uv - vec2(1.0, 0.58)) * vec2(1.5, 1.2))), 0.0, 1.0);
    float bright = smoothstep(0.22, 0.85, gas * (0.55 + 0.9 * glow));
    vec3 col = mix(vec3(0.07, 0.07, 0.10), vec3(0.30, 0.32, 0.45), smoothstep(0.0, 0.45, bright));
    col = mix(col, vec3(0.58, 0.66, 0.92), smoothstep(0.35, 0.75, bright));
    col = mix(col, vec3(0.92, 0.95, 1.0), smoothstep(0.72, 1.0, bright) * glow);
    // A grey-blue haze over the whole field: in the image even the darker
    // parts are veiled.
    float haze = nb_fbm(p * 0.6 + 11.0 + 0.5 * q);
    col = mix(col, vec3(0.34, 0.36, 0.48), 0.35 * smoothstep(0.3, 0.7, haze) * (1.0 - bright));

    // THE DUST: filaments, brown in the shadow and rusty where they meet the
    // lit gas; thicker away from the glows.
    float lanes = nb_ridge(p * 1.3 + 2.0 * q);
    float shade = smoothstep(0.35, 0.75, lanes) * (0.5 + 0.5 * (1.0 - glow));
    float rim = smoothstep(0.3, 0.6, gas) * (1.0 - smoothstep(0.6, 0.9, gas));
    vec3 dustCol = mix(vec3(0.20, 0.12, 0.08), vec3(0.62, 0.38, 0.24), rim * rim);
    col = mix(col, dustCol, clamp(shade * 0.6 * dust, 0.0, 1.0));

    // Thin dark wisps and pillars across the lit gas.
    float wisps = smoothstep(0.55, 0.8, nb_ridge(p * 2.6 + 3.0 * q + 17.0));
    col *= 1.0 - clamp(0.45 * wisps * dust * (0.4 + 0.6 * bright), 0.0, 0.8);

    // The dark lower-left corner, tinted brown.
    float dark = smoothstep(1.15, 0.2, uv.x + 1.2 * uv.y);
    col = mix(col, vec3(0.15, 0.09, 0.06), clamp(dark * (0.4 + 0.2 * dust), 0.0, 0.8));

    // The orange knot low in the middle.
    float knot = exp(-length((uv - vec2(0.5, 0.3)) * vec2(16.0, 10.0))) * (0.4 + 1.2 * nb_fbm(p * 6.0));
    col += vec3(1.0, 0.55, 0.25) * knot;

    // THE STARS: faint and many, medium, and a few bright with spikes.
    vec3 st = 0.5 * nb_stars(uv, 90.0, 0.10, 100.0, 0.0)
            + nb_stars(uv + 0.37, 30.0, 0.18, 400.0, 0.0)
            + 1.6 * nb_stars(uv + 0.71, 6.0, 0.20, 2300.0, 1.0);
    col += st * starsAmount;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
